const std::size_t kBitsPerKey = 10;  // Number of bits to allocate per inserted key
const std::size_t kHashesPerKey = 12;  // Number of hash functions to use per key
const std::size_t bits = bloom_filter.size() * 8;
if (bits < kBitsPerKey) return false;

const std::size_t num_hashes = std::min(kHashesPerKey, bits / kBitsPerKey);
std::size_t hash = std::hash<std::string>{}(key.data(), key.size());
for (std::size_t i = 0; i < num_hashes; i++) {
    hash = std::hash<std::size_t>{}(hash);
    std::size_t bit_pos = hash % bits;
    if ((bloom_filter[bit_pos / 8] & (1 << (bit_pos % 8))) == 0) {
        return false;
    }
}
return true;
